<?php
namespace RobwForge;
defined('ABSPATH') || exit;
final class Store {
 const PREFIX='robw_forge_repo_', LIMIT=12582912;
 static function slug($id){return is_string($id)&&preg_match('/^[a-z0-9][a-z0-9-]{0,62}$/D',$id);}
 static function read($id){if(!self::slug($id))throw new \InvalidArgumentException('Invalid repository');global $wpdb;$s=$wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",self::PREFIX.$id));if($s===null)return[null,null];$r=json_decode($s,true,512,JSON_THROW_ON_ERROR);if(!is_array($r)||($r['schema']??0)!==1)throw new \RuntimeException('Repository state corrupt');return[$s,$r];}
 static function mutate($id,$fn){global $wpdb;for($i=0;$i<24;$i++){[$old,$r]=self::read($id);$result=$fn($r);$json=wp_json_encode($r);if($json===false||strlen($json)>self::LIMIT)throw new \InvalidArgumentException('Storage quota');if($old===null)$ok=$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$wpdb->options} (option_name,option_value,autoload) VALUES (%s,%s,'no')",self::PREFIX.$id,$json));else$ok=$wpdb->query($wpdb->prepare("UPDATE {$wpdb->options} SET option_value=%s WHERE option_name=%s AND BINARY option_value=BINARY %s",$json,self::PREFIX.$id,$old));if($ok===false)throw new \RuntimeException('Persistence failure');if($ok===1||$json===$old)return$result;usleep(random_int(1000,5000));}throw new \RuntimeException('Repository busy',409);}
 static function allowed($r,$uid,$write=false){return$r&&$uid&&get_userdata($uid)&&user_can($uid,'read')&&((int)$r['owner']===$uid||in_array($r['members'][(string)$uid]??'', $write?['write']:['read','write'],true));}
 static function require_access($r,$uid,$write=false){if(!self::allowed($r,$uid,$write))throw new \RuntimeException('Repository not found',404);}
 static function owner($r,$uid){self::require_access($r,$uid);if((int)$r['owner']!==$uid)throw new \RuntimeException('Owner required',403);}
 static function create($id,$uid){if(!user_can($uid,'edit_posts'))throw new \RuntimeException('Repository creation denied',403);return self::mutate($id,function(&$r)use($uid){if($r!==null)throw new \RuntimeException('Repository exists',409);$r=['schema'=>1,'owner'=>$uid,'members'=>[],'refs'=>[],'objects'=>[],'issues'=>[],'hooks'=>[],'events'=>[],'created'=>time()];return['created'=>true];});}
 static function list_ids(){global $wpdb;$ids=$wpdb->get_col($wpdb->prepare("SELECT option_name FROM {$wpdb->options} WHERE option_name LIKE %s ORDER BY option_name LIMIT 101",$wpdb->esc_like(self::PREFIX).'%'));if(count($ids)>100)throw new \RuntimeException('Repository listing quota');return array_map(function($id){return substr($id,strlen(self::PREFIX));},$ids);}
 static function manage($id,$uid,$input){$secret=bin2hex(random_bytes(32));return self::mutate($id,function(&$r)use($uid,$input,$secret){self::require_access($r,$uid,true);$op=$input['op']??'';if($op==='member'){self::owner($r,$uid);$u=get_user_by('login',$input['login']??'');$role=$input['role']??'';if(!$u||!in_array($role,['read','write','remove'],true)||(int)$u->ID===(int)$r['owner'])throw new \InvalidArgumentException('Invalid member');if($role==='remove')unset($r['members'][(string)$u->ID]);else$r['members'][(string)$u->ID]=$role;if(count($r['members'])>100)throw new \InvalidArgumentException('Member quota');return['updated'=>true];}if($op==='issue'){if(count($r['issues'])>=100)throw new \InvalidArgumentException('Issue quota');$title=trim($input['title']??'');$body=$input['body']??'';if(!$title||strlen($title)>200||strlen($body)>8192)throw new \InvalidArgumentException('Invalid issue');$n=count($r['issues'])+1;$r['issues'][(string)$n]=['title'=>$title,'body'=>$body,'author'=>$uid,'open'=>true,'comments'=>[],'created'=>time()];return['issue'=>$n];}if(in_array($op,['comment','close','reopen'],true)){$n=(string)($input['issue']??'');if(!isset($r['issues'][$n]))throw new \InvalidArgumentException('Issue not found');if($op==='comment'){$body=$input['body']??'';if(!$body||strlen($body)>8192||count($r['issues'][$n]['comments'])>=100)throw new \InvalidArgumentException('Comment quota');$r['issues'][$n]['comments'][]=['body'=>$body,'author'=>$uid,'created'=>time()];}else$r['issues'][$n]['open']=$op==='reopen';return['updated'=>true];}if($op==='hook'){self::owner($r,$uid);$url=$input['url']??'';Hooks::validate_url($url);if(count($r['hooks'])>=5)throw new \InvalidArgumentException('Webhook quota');$hid=bin2hex(random_bytes(8));$r['hooks'][$hid]=['url'=>$url,'key'=>Hooks::seal($secret)];return['id'=>$hid,'secret'=>$secret];}if($op==='delete-hook'){self::owner($r,$uid);$hid=$input['id']??'';unset($r['hooks'][$hid]);foreach($r['events']as&$e)unset($e['deliveries'][$hid]);return['updated'=>true];}throw new \InvalidArgumentException('Unknown operation');});}
 static function push($id,$uid,$commands,$new){$eid=bin2hex(random_bytes(16));return self::mutate($id,function(&$r)use($id,$uid,$commands,$new,$eid){self::require_access($r,$uid,true);$r=Git::update($r,$commands,$new);foreach($r['events']as$k=>$e)if($e['created']<time()-604800&&Hooks::complete($e))unset($r['events'][$k]);while(count($r['events'])>=100){$found=false;foreach($r['events']as$k=>$event)if(Hooks::complete($event)){unset($r['events'][$k]);$found=true;break;}if(!$found)throw new \InvalidArgumentException('Webhook outbox quota');}$updates=[];foreach($commands as$ref=>[$old,$next])$updates[]=['ref'=>$ref,'before'=>$old,'after'=>$next,'created'=>$old===Git::ZERO,'deleted'=>$next===Git::ZERO];$e=['id'=>$eid,'event'=>'push','repository'=>$id,'actor'=>$uid,'updates'=>$updates,'created'=>time(),'deliveries'=>[]];foreach($r['hooks']as$hid=>$hook)$e['deliveries'][$hid]=['attempts'=>0,'next'=>time(),'status'=>'pending','lease'=>null,'until'=>0,'code'=>null];$r['events'][$eid]=$e;return$eid;});}
 static function overview($r,$uid){return['owner'=>$r['owner'],'members'=>$r['members'],'refs'=>$r['refs'],'issues'=>$r['issues'],'hooks'=>(int)$r['owner']===$uid?array_map(function($h){return['url'=>$h['url']];},$r['hooks']):[],'events'=>(int)$r['owner']===$uid?$r['events']:[],'objects'=>count($r['objects'])];}
}
